from pathlib import Path
import os, subprocess,sys,tempfile,shutil
R=Path(__file__).resolve().parents[3];T=R/'software/tests/tesla_vehicle';from host_dependencies import cache, mbed
with tempfile.TemporaryDirectory(prefix='multi-tesla-',dir=os.environ['TMPDIR']) as td:
 d=Path(td)
 flags=['-DTESLA_NIMBLE_HOST_TEST=1','-DTESLA_BLE_USE_NIMBLE=1','-DCONFIG_BT_NIMBLE_HOST_TASK_STACK_SIZE=8192','-DCONFIG_BT_NIMBLE_PINNED_TO_CORE=0','-std=c++17','-Wall','-Wextra','-Werror','-Wno-misleading-indentation','-fno-exceptions','-fno-rtti','-pthread','-DTESLA_BLE_MODULE_HOST_TEST','-DTESLA_BLE_HOST_FILESYSTEM','-DTESLA_BLE_MANUAL_VEHICLE_UI=1','-DBLUETOOTH_CONFIG_PATH="'+str(d/'config')+'"','-I'+str(T/'host'),'-I'+str(R/'software/lib/TeslaBLEClean/include'),'-I'+str(mbed/'include')]
 if os.environ.get('TESLA_NIMBLE_REAL_DRAIN_HEADER'):flags+=['-DTESLA_NIMBLE_REAL_DRAIN_HEADER="'+os.environ['TESLA_NIMBLE_REAL_DRAIN_HEADER']+'"']
