 libs=[cache/'mbedtls'/n for n in ('library/libmbedcrypto.a','3rdparty/everest/libeverest.a','3rdparty/p256-m/libp256m.a')]
 subprocess.run(['g++',*flags,*map(str,src),*map(str,libs),'-o',str(d/'test')],check=True)
 if os.environ.get('TESLA_NIMBLE_MODULE_BINARY_OUT'):shutil.copy2(d/'test',os.environ['TESLA_NIMBLE_MODULE_BINARY_OUT'])
 for mode in os.environ.get('TESLA_NIMBLE_MODULE_MODES','init-fail host-create-fail stop-fail foreign-stack pairing generate notify-only indicate-and-notify delayed-pair connect-timeout pending-connect-stop late-connect-stop quiesce-disconnect-race quiesce-retains quiesce-error-delayed connect-repeat connect-repeat-late-success connect-repeat-sdk-timeout connect-repeat-refused connect-repeat-identity connect-repeat-missing connect-repeat-blocked connect-repeat-cancel-error connect-repeat-cancel-already connect-repeat-preconnect-disconnect connect-repeat-preconnect-stall connect-repeat-preconnect-late-connect connect-repeat-preconnect-undrained no-card decline link-drop profile-switch partial-pair late-response multi delete-first idle-enabled legacy-key legacy-session legacy-bench corrupt-profiles empty-legacy unbound-inert-legacy soc-reservation soc-wake-slow soc-wake-never soc-cancel-before-wake soc-wake-tx-fail soc-wake-drop-waitwake soc-guided-timeout soc-auto soc-auto-stop soc-auto-interval soc-auto-recvtime soc-auto-charge-idle soc-auto-charge-cycle soc-auto-charge-resume soc-auto-initial-retry soc-wake-followup soc-auto-wake-followup soc-info-silent soc-auto-post-pair soc-auto-identity-origin soc-auto-snapshot-retry snapshot-interleave').split():
  subprocess.run([str(d/'test'),mode],check=True,timeout=45)
